#!/usr/bin/env bash
# Brings up the local stack: one neard validator, the real 3.18.0 signer contract, two real
# mpc-node participants (non-TEE, local attestation authority), domains 0-3 generated by the
# nodes, and an anvil chain with chain id 84532 that the nodes use as the `Base` foreign chain.
#
# Usage: scripts/localstack/up.sh            (fresh start; wipes the run dir)
# Env:   LOCALSTACK_DIR   run dir            (default ~/development/near-hackathon-research/localstack-run)
#        NEARD, MPC_NODE  binaries           (default the research bin dir)
#        SIGNER_WASM      signer contract    (default the testnet 3.18.0 code fetched by view_code)
#        MPC_SRC          near/mpc checkout  (for deployment/localnet)
set -euo pipefail

HERE="$(cd "$(dirname "$0")" && pwd)"
RESEARCH="$HOME/development/near-hackathon-research"
R="${LOCALSTACK_DIR:-$RESEARCH/localstack-run}"
NEARD="${NEARD:-$RESEARCH/bin/bin/neard}"
MPC_NODE="${MPC_NODE:-$RESEARCH/bin/bin/mpc-node}"
SIGNER_WASM="${SIGNER_WASM:-$RESEARCH/signer-wasm/v1.signer-prod.testnet.wasm}"
MPC_SRC="${MPC_SRC:-$RESEARCH/src/mpc-3.18.0}"
N=2
ANVIL_PORT=8545
# anvil reports `finalized` = latest - 2 * slots_in_an_epoch, so with 2 slots finality lags 4 blocks.
ANVIL_SLOTS=2

for f in "$NEARD" "$MPC_NODE" "$SIGNER_WASM"; do [[ -f "$f" ]] || { echo "missing $f" >&2; exit 1; }; done
for c in anvil cast node curl jq; do command -v "$c" >/dev/null || { echo "missing $c" >&2; exit 1; }; done

"$HERE/down.sh" >/dev/null 2>&1 || true
rm -rf "$R/near" "$R"/mpc-node-* "$R/state.json"
mkdir -p "$R/logs" "$R/pids"

bg() { # name, command...
  local name="$1"; shift
  nohup "$@" >"$R/logs/$name.log" 2>&1 &
  echo $! >"$R/pids/$name.pid"
  echo "started $name pid $!"
}

wait_for() { # description, command
  local what="$1" cmd="$2" i
  for i in $(seq 1 180); do
    if eval "$cmd" >/dev/null 2>&1; then return 0; fi
    sleep 2
  done
  echo "timed out waiting for $what" >&2; exit 1
}

echo "== anvil (chain id 84532, finalized = latest - $((2 * ANVIL_SLOTS)), mining on demand)"
bg anvil anvil --chain-id 84532 --port "$ANVIL_PORT" --slots-in-an-epoch "$ANVIL_SLOTS" --no-mining --order fees
wait_for anvil "cast chain-id --rpc-url http://127.0.0.1:$ANVIL_PORT"
cast rpc --rpc-url "http://127.0.0.1:$ANVIL_PORT" anvil_mine 8 >/dev/null

echo "== neard localnet"
"$NEARD" --home "$R/near" init --chain-id mpc-localnet >/dev/null 2>&1
cp -rf "$MPC_SRC/deployment/localnet/." "$R/near"
rm -rf "$R/near/tee"
# Keep the localnet small on disk.
jq '.gc_num_epochs_to_keep = 3' "$R/near/config.json" >"$R/near/config.tmp" && mv "$R/near/config.tmp" "$R/near/config.json"
bg neard env NEAR_ENV=mpc-localnet "$NEARD" --home "$R/near" run
wait_for neard "curl -sf localhost:3030/status"
# The launch script waits before starting nodes: starting them too early can halt the chain.
sleep 20

echo "== accounts and signer contract"
node "$HERE/bootstrap.mjs" accounts "$SIGNER_WASM"

NODE_PUBKEY=$(jq -r .public_key "$R/near/node_key.json")
for i in $(seq 1 $N); do
  name="mpc-node-$i"
  account="$name.test.near"
  home="$R/$name"
  mkdir -p "$home"
  cat >"$home/mpc-config.toml" <<EOF
home_dir = "$home"

[near_init]
chain_id = "mpc-localnet"
download_genesis = false
boot_nodes = "$NODE_PUBKEY@127.0.0.1:24566"
genesis_path = "$R/near/genesis.json"
rpc_addr = "127.0.0.1:$((3030 + i))"
network_addr = "127.0.0.1:$((24566 + i))"

[secrets]
secret_store_key_hex = "11111111111111111111111111111111"

[tee]
image_hash = "sha256:8b40f81f77b8c22d6c777a6e14d307a1d11cb55ab83541fbb8575d02d86a74b0"
latest_allowed_hash_file_path = "$home/LATEST_ALLOWED_HASH_FILE.txt"

[tee.authority]
type = "local"

[log]
format = "plain"
filter = "info"

[node]
my_near_account_id = "$account"
near_responder_account_id = "$account"
number_of_responder_keys = 1
web_ui = "127.0.0.1:$((8080 + i))"
migration_web_ui = "127.0.0.1:$((8090 + i))"
pprof_bind_address = "127.0.0.1:$((34000 + i))"
cores = 2

[node.triple]
concurrency = 1
desired_triples_to_buffer = 16
timeout_sec = 120
parallel_triple_generation_stagger_time_sec = 1

[node.presignature]
concurrency = 2
desired_presignatures_to_buffer = 8
timeout_sec = 60

[node.signature]
timeout_sec = 60
online_presign = true

[node.indexer]
validate_genesis = false
sync_mode = "Latest"
concurrency = 1
mpc_contract_id = "mpc-contract.test.near"
finality = "optimistic"

[node.ckd]
timeout_sec = 60

[node.foreign_chains.base]
timeout_sec = 10
max_retries = 3
expected_network_fingerprint = "84532"

[node.foreign_chains.base.providers.anvil]
rpc_url = "http://127.0.0.1:$ANVIL_PORT"

[node.foreign_chains.base.providers.anvil.auth]
kind = "none"
EOF
  bg "$name" env RUST_LOG=info "$MPC_NODE" start-with-config-file "$home/mpc-config.toml"
done
for i in $(seq 1 $N); do wait_for "mpc-node-$i web ui" "curl -sf localhost:$((8080 + i))/public_data"; done

echo "== contract init, domains, Base provider vote"
node "$HERE/bootstrap.mjs" init $N

echo "== stack is up. State: $R/state.json  Logs: $R/logs"
